   jobs.append({'job':name,'parent_shard':old,'wave':half,'records':len(part),'first_source_ordinal':part[0]['source_ordinal'],'last_source_ordinal':part[-1]['source_ordinal'],'exact_manifest':p.name,'manifest_sha256':sha(p),'observed_parent_wall_seconds_per_committed_row':observed,'linear_residual_seconds_estimate_including_parent_average_overhead':estimate,'conservative_planning_seconds_1_25x_plus90':1.25*estimate+90,'hard_seconds_proposed':900})
